<!DOCTYPE html>
<html lang="ro">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
  <meta name="robots" content="noindex, nofollow">
  <meta name="theme-color" content="#061a15">
  <title>Verifică adresa de email — Nordvale</title>
  <meta name="description" content="Confirmă adresa de email asociată contului Nordvale.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&display=swap" rel="stylesheet">
  <style>
    :root{
      --pine-950:#061a15;--pine-900:#09251d;--pine-850:#0d3027;--pine-800:#123b30;--pine-700:#1b5242;
      --acid:#dffc62;--ember:#f27b4a;--cream:#fffdf6;--oat:#f0ecdf;--moss:#b7c9a3;--ink:#16231e;
      --shadow-lift:0 38px 110px -42px rgba(6,26,21,.68);--shadow-card:0 20px 58px -30px rgba(6,26,21,.48)
    }
    *{box-sizing:border-box}html{background:var(--oat)}body{margin:0;min-height:100vh;overflow-x:hidden;background:var(--oat);color:var(--ink);font-family:'DM Sans',system-ui,sans-serif;text-rendering:optimizeLegibility}button,input{font:inherit}button,a{-webkit-tap-highlight-color:transparent}a{color:inherit;text-decoration:none}[hidden]{display:none!important}::selection{background:var(--acid);color:var(--pine-950)}
    .page{min-height:100svh;position:relative;isolation:isolate}.page:before{content:"";position:fixed;inset:0;z-index:30;pointer-events:none;opacity:.055;mix-blend-mode:multiply;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.52'/%3E%3C/svg%3E")}.topo{background-image:radial-gradient(circle at 22% 12%,rgba(223,252,98,.15),transparent 27%),radial-gradient(circle at 82% 18%,rgba(242,123,74,.1),transparent 23%),url("data:image/svg+xml,%3Csvg width='760' height='760' viewBox='0 0 760 760' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' stroke='%23ffffff' stroke-opacity='.06' stroke-width='1.15'%3E%3Cpath d='M74 208c48-107 174-168 282-110 84 45 97 151 37 216-55 60-150 44-205 105-58 65-56 176-145 207-86 30-177-48-148-137 27-83 127-91 151-170 15-48 0-79 28-111Z'/%3E%3Cpath d='M111 229c39-85 139-133 225-87 67 36 77 120 29 172-44 48-120 35-164 84-47 52-45 141-116 166-69 24-142-38-118-110 21-67 101-73 120-136 12-38 0-63 24-89Z'/%3E%3Cpath d='M466 433c62-88 182-99 250-14 59 74 21 178-66 210-77 29-150-17-215 30-53 39-64 125-133 127-76 3-128-79-85-142 39-57 116-36 164-86 40-42 43-81 85-125Z'/%3E%3C/g%3E%3C/svg%3E");background-size:auto,auto,760px 760px}
    .header-wrap{position:fixed;top:0;left:0;right:0;z-index:50;padding:max(10px,env(safe-area-inset-top)) 12px 0}.header{max-width:1480px;margin:0 auto;min-height:62px;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 12px;border:1px solid rgba(255,255,255,.12);border-radius:20px;background:rgba(6,26,21,.82);box-shadow:0 24px 70px -42px rgba(0,0,0,.92);backdrop-filter:blur(22px) saturate(130%)}.brand{min-width:0;display:flex;align-items:center;gap:10px;color:white}.brand-mark{width:42px;height:42px;flex:0 0 auto;display:grid;place-items:center;border-radius:14px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.1)}.brand-name{display:block;line-height:1;font:600 20px/1 'Fraunces',serif}.brand-sub{display:block;margin-top:5px;max-width:210px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:rgba(255,255,255,.52);font-size:8px;font-weight:700;letter-spacing:.24em;text-transform:uppercase}.header-actions{flex:0 0 auto;display:flex;align-items:center;gap:7px}.nav-link{display:none;align-items:center;gap:8px;padding:10px 15px;border-radius:999px;color:rgba(255,255,255,.78);font-size:14px;font-weight:700}.nav-link:hover{background:rgba(255,255,255,.08);color:white}.ticket-btn{display:inline-flex;flex:0 0 auto;align-items:center;justify-content:center;gap:7px;white-space:nowrap;min-height:40px;padding:0 14px;border:0;border-radius:999px;background:var(--acid);color:var(--pine-950);font-size:12px;font-weight:800;box-shadow:0 18px 54px -24px rgba(223,252,98,.58)}.menu-btn{width:40px;height:40px;flex:0 0 auto;display:grid;place-items:center;border:1px solid rgba(255,255,255,.16);border-radius:999px;background:transparent;color:white;cursor:pointer}
    .mobile-menu{position:fixed;inset:0;z-index:80;display:grid;grid-template-rows:auto 1fr;background:var(--pine-950);color:white;transform:translateX(100%);transition:transform .38s cubic-bezier(.22,.8,.2,1)}.mobile-menu.open{transform:translateX(0)}.mobile-menu-head{display:flex;align-items:center;justify-content:space-between;padding:max(18px,env(safe-area-inset-top)) 18px 14px}.mobile-menu-body{padding:24px 18px max(30px,env(safe-area-inset-bottom));display:flex;flex-direction:column;justify-content:space-between}.mobile-menu nav{display:grid;gap:8px}.mobile-menu nav a{padding:16px 2px;border-bottom:1px solid rgba(255,255,255,.1);font:600 30px/1.08 'Fraunces',serif}
    .main{min-height:100svh;display:grid;grid-template-columns:minmax(0,1fr);padding-top:86px}.visual{position:relative;min-height:390px;overflow:hidden;background:var(--pine-950);color:white}.visual-bg{position:absolute;inset:0}.visual-bg img{width:100%;height:100%;object-fit:cover;object-position:center 45%;filter:saturate(.76) contrast(1.04);opacity:.68}.visual-bg:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(6,26,21,.12),rgba(6,26,21,.54) 58%,rgba(6,26,21,.98)),linear-gradient(90deg,rgba(6,26,21,.4),transparent 64%)}.visual-content{position:relative;z-index:2;min-height:390px;padding:38px 20px 25px;display:flex;flex-direction:column;justify-content:flex-end}.eyebrow{display:inline-flex;width:max-content;align-items:center;gap:8px;margin-bottom:16px;padding:8px 11px;border:1px solid rgba(255,255,255,.16);border-radius:999px;background:rgba(6,26,21,.28);color:rgba(255,255,255,.84);backdrop-filter:blur(12px);font-size:10px;font-weight:800;letter-spacing:.18em;text-transform:uppercase}.eyebrow-dot{width:7px;height:7px;border-radius:50%;background:var(--acid);box-shadow:0 0 0 5px rgba(223,252,98,.14)}.visual-title{max-width:700px;margin:0;font:600 clamp(38px,9.4vw,72px)/.96 'Fraunces',serif;letter-spacing:-.045em}.visual-title em{color:var(--acid);font-style:normal}.visual-copy{max-width:590px;margin:16px 0 0;color:rgba(255,255,255,.68);font-size:15px;line-height:1.65}.trail-note{margin-top:24px;display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;max-width:560px;padding:13px;border:1px solid rgba(255,255,255,.13);border-radius:20px;background:rgba(6,26,21,.54);backdrop-filter:blur(18px)}.trail-note-icon{width:46px;height:46px;display:grid;place-items:center;border-radius:15px;background:var(--acid);color:var(--pine-950)}.trail-note strong{display:block;font-size:13px;color:white}.trail-note span{display:block;margin-top:4px;color:rgba(255,255,255,.52);font-size:11px;line-height:1.5}.route{position:absolute;top:12%;right:-8%;width:min(65vw,620px);height:auto;opacity:.82;pointer-events:none}.route path.shadow{fill:none;stroke:rgba(255,255,255,.13);stroke-width:10;stroke-linecap:round}.route path.main{fill:none;stroke:rgba(223,252,98,.76);stroke-width:2;stroke-linecap:round;stroke-dasharray:7 12;animation:dash 12s linear infinite}@keyframes dash{to{stroke-dashoffset:-190}}
    .auth{position:relative;background:var(--oat);padding:24px 16px max(36px,env(safe-area-inset-bottom))}.auth:before{content:"";position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(rgba(9,37,29,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(9,37,29,.045) 1px,transparent 1px);background-size:30px 30px;mask-image:linear-gradient(to bottom,black,transparent 88%)}.auth-inner{position:relative;z-index:2;width:min(100%,560px);margin:0 auto}.back{display:inline-flex;align-items:center;gap:8px;margin:0 0 22px;color:rgba(22,35,30,.62);font-size:13px;font-weight:700}.form-card{padding:24px 18px;border:1px solid rgba(9,37,29,.1);border-radius:28px;background:rgba(255,253,246,.92);box-shadow:var(--shadow-lift);backdrop-filter:blur(18px)}.form-kicker{margin:0 0 10px;color:var(--pine-700);font-size:10px;font-weight:800;letter-spacing:.2em;text-transform:uppercase}.form-title{margin:0;font:600 clamp(32px,8vw,46px)/1 'Fraunces',serif;letter-spacing:-.035em}.form-copy{margin:13px 0 0;color:rgba(22,35,30,.6);font-size:13px;line-height:1.65}
    .mail-visual{position:relative;margin:24px auto 18px;width:142px;height:112px}.mail-shadow{position:absolute;left:18px;right:18px;bottom:1px;height:20px;border-radius:50%;background:rgba(6,26,21,.15);filter:blur(13px)}.envelope{position:absolute;inset:8px 5px 10px;border-radius:20px;background:var(--pine-950);box-shadow:0 24px 50px -28px rgba(6,26,21,.8);overflow:hidden;transform:rotate(-2deg)}.envelope:before{content:"";position:absolute;left:0;right:0;top:0;height:58%;clip-path:polygon(0 0,50% 68%,100% 0);background:var(--pine-800)}.envelope:after{content:"";position:absolute;inset:0;clip-path:polygon(0 100%,0 42%,50% 74%,100% 42%,100% 100%);background:var(--pine-900)}.letter{position:absolute;left:28px;right:28px;top:0;height:68px;padding:13px;border-radius:13px 13px 8px 8px;background:var(--cream);box-shadow:0 16px 24px -20px rgba(0,0,0,.4);transform:translateY(9px) rotate(2deg);z-index:2}.letter-line{display:block;height:5px;margin-bottom:6px;border-radius:999px;background:rgba(6,26,21,.12)}.letter-line:first-child{width:62%;background:var(--acid)}.letter-line:nth-child(2){width:82%}.letter-line:nth-child(3){width:48%}.mail-badge{position:absolute;right:-3px;top:0;z-index:4;width:42px;height:42px;display:grid;place-items:center;border:5px solid var(--cream);border-radius:50%;background:var(--ember);color:white;box-shadow:0 12px 26px -15px rgba(242,123,74,.8)}
    .status-box{display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;margin:20px 0 0;padding:14px;border:1px solid rgba(27,82,66,.13);border-radius:18px;background:rgba(183,201,163,.18)}.status-icon{width:40px;height:40px;display:grid;place-items:center;border-radius:13px;background:var(--pine-950);color:var(--acid)}.status-box strong{display:block;font-size:12px}.status-box span{display:block;margin-top:4px;color:rgba(22,35,30,.57);font-size:11px;line-height:1.5}.email-chip{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:16px;padding:12px 13px;border:1px solid rgba(9,37,29,.12);border-radius:16px;background:white}.email-chip span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;font-weight:800}.email-chip button{flex:0 0 auto;border:0;background:transparent;color:var(--pine-700);font-size:11px;font-weight:800;cursor:pointer}
    .actions{display:grid;gap:10px;margin-top:22px}.primary,.secondary{min-height:52px;display:flex;align-items:center;justify-content:center;gap:9px;border-radius:16px;font-size:13px;font-weight:800;cursor:pointer}.primary{border:0;background:var(--pine-950);color:white;box-shadow:0 18px 44px -26px rgba(6,26,21,.9)}.primary:hover{background:var(--pine-800)}.primary:disabled{cursor:not-allowed;opacity:.58}.secondary{border:1px solid rgba(9,37,29,.14);background:rgba(255,255,255,.72);color:var(--ink)}.secondary:hover{background:white;border-color:rgba(9,37,29,.24)}.countdown{margin-top:12px;text-align:center;color:rgba(22,35,30,.48);font-size:11px}.countdown strong{color:var(--ink)}
    .help-grid{display:grid;grid-template-columns:1fr;gap:10px;margin-top:20px}.help-item{display:grid;grid-template-columns:auto minmax(0,1fr);gap:10px;padding:12px;border:1px solid rgba(9,37,29,.08);border-radius:16px;background:rgba(255,255,255,.48)}.help-item svg{color:var(--pine-700)}.help-item strong{display:block;font-size:11px}.help-item span{display:block;margin-top:3px;color:rgba(22,35,30,.5);font-size:10px;line-height:1.45}
    .edit-panel{margin-top:18px;padding-top:18px;border-top:1px solid rgba(9,37,29,.09)}.field{display:grid;gap:7px}.field label{font-size:12px;font-weight:800}.input{width:100%;min-height:50px;padding:0 14px;border:1px solid rgba(9,37,29,.14);border-radius:16px;background:white;color:var(--ink);outline:none}.input:focus{border-color:var(--pine-700);box-shadow:0 0 0 4px rgba(27,82,66,.09)}.field-error{min-height:16px;margin-top:5px;color:#a74633;font-size:11px;font-weight:700}.edit-actions{display:grid;grid-template-columns:1fr;gap:9px;margin-top:12px}.success{text-align:center;padding:14px 0 4px}.success-mark{width:82px;height:82px;margin:8px auto 18px;display:grid;place-items:center;border-radius:28px;background:var(--acid);color:var(--pine-950);box-shadow:0 20px 48px -25px rgba(223,252,98,.9);transform:rotate(-4deg)}.success h3{margin:0;font:600 31px/1.02 'Fraunces',serif}.success p{max-width:390px;margin:12px auto 0;color:rgba(22,35,30,.58);font-size:13px;line-height:1.65}.success-badge{display:inline-flex;align-items:center;gap:7px;margin-top:16px;padding:8px 11px;border-radius:999px;background:rgba(27,82,66,.1);color:var(--pine-700);font-size:10px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.success-actions{display:grid;gap:10px;margin-top:24px}.toast{position:fixed;left:50%;bottom:max(18px,env(safe-area-inset-bottom));z-index:100;max-width:calc(100vw - 24px);padding:12px 16px;border-radius:999px;background:var(--pine-950);color:white;box-shadow:0 20px 50px -24px rgba(0,0,0,.8);font-size:12px;font-weight:700;opacity:0;pointer-events:none;transform:translate(-50%,18px);transition:.28s ease}.toast.show{opacity:1;transform:translate(-50%,0)}
    @media(max-width:390px){.brand-sub{display:none}.brand-name{font-size:18px}.ticket-btn{padding:0 12px}.visual-content{padding-left:16px;padding-right:16px}.form-card{padding:22px 15px}.email-chip{align-items:flex-start;flex-direction:column}.email-chip button{padding:2px 0}}
    @media(min-width:600px){.auth{padding:42px 32px 50px}.form-card{padding:34px}.help-grid{grid-template-columns:1fr 1fr}.edit-actions{grid-template-columns:1fr 1fr}.actions,.success-actions{grid-template-columns:1fr 1fr}.actions .primary:first-child,.success-actions .primary:first-child{grid-column:1/-1}}
    @media(min-width:900px){.nav-link{display:inline-flex}.menu-btn{display:none}.main{grid-template-columns:minmax(0,1.05fr) minmax(470px,.95fr);padding-top:0}.visual{position:sticky;top:0;min-height:100svh}.visual-content{min-height:100svh;padding:130px clamp(42px,6vw,90px) 62px}.auth{min-height:100svh;display:flex;align-items:center;padding:110px clamp(32px,5vw,72px) 50px}.form-card{padding:38px}.back{margin-bottom:28px}.route{top:12%;right:-10%;width:min(48vw,670px)}}
    @media(min-width:1200px){.header-wrap{padding-left:18px;padding-right:18px}.header{padding-left:16px;padding-right:16px}.visual-title{font-size:74px}.visual-copy{font-size:16px}.auth-inner{width:min(100%,590px)}}
    @media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}}
  </style>
</head>
<body>
<div class="page">
  <div class="header-wrap">
    <header class="header">
      <a class="brand" href="/" aria-label="Nordvale, pagina principală"><span class="brand-mark"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 18 9 7l3 6 3-9 5 14H4Z"/><path d="M8 18v2m8-2v2"/></svg></span><span><span class="brand-name">Nordvale</span><span class="brand-sub">Wild reserve & adventure park</span></span></a>
      <div class="header-actions"><a class="nav-link" href="/experiente">Experiențe</a><a class="nav-link" href="/planifica">Planifică vizita</a><a class="ticket-btn" href="/bilete"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 8a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v2a2 2 0 1 0 0 4v2a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-2a2 2 0 1 0 0-4V8Z"/><path d="M13 6v12"/></svg>Bilete</a><button class="menu-btn" id="menuOpen" type="button" aria-label="Deschide meniul"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button></div>
    </header>
  </div>

  <aside class="mobile-menu" id="mobileMenu" aria-hidden="true">
    <div class="mobile-menu-head"><a class="brand" href="/"><span class="brand-mark"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 18 9 7l3 6 3-9 5 14H4Z"/></svg></span><span class="brand-name">Nordvale</span></a><button class="menu-btn" id="menuClose" type="button" aria-label="Închide meniul"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>
    <div class="mobile-menu-body"><nav><a href="/">Acasă</a><a href="/experiente">Experiențe</a><a href="/planifica">Planifică vizita</a><a href="/autentificare">Autentificare</a></nav><p style="color:rgba(255,255,255,.45);font-size:12px;line-height:1.6">Ai nevoie de ajutor?<br><strong style="color:white">support@nordvale.demo</strong></p></div>
  </aside>

  <main class="main">
    <section class="visual topo" aria-label="Verificare email Nordvale">
      <div class="visual-bg"><img src="https://images.unsplash.com/photo-1511497584788-876760111969?auto=format&fit=crop&w=1800&q=86" alt="Potecă de pădure luminată printre brazi"></div>
      <svg class="route" viewBox="0 0 650 480" fill="none" aria-hidden="true"><path class="shadow" d="M42 405c64-15 87-91 155-108 68-18 117 39 178-3 61-43 43-122 111-157 40-21 87-8 122-46"/><path class="main" d="M42 405c64-15 87-91 155-108 68-18 117 39 178-3 61-43 43-122 111-157 40-21 87-8 122-46"/><circle cx="42" cy="405" r="8" fill="#DFFC62"/><circle cx="608" cy="91" r="10" fill="#F27B4A"/></svg>
      <div class="visual-content">
        <div class="eyebrow"><span class="eyebrow-dot"></span>Cont aproape gata</div>
        <h1 class="visual-title">Un singur pas până la următoarea <em>aventură.</em></h1>
        <p class="visual-copy">Confirmarea adresei de email ne ajută să îți păstrăm biletele, comenzile și abonamentele într-un singur loc sigur.</p>
        <div class="trail-note"><span class="trail-note-icon"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16v16H4z"/><path d="m4 7 8 6 8-6"/></svg></span><span><strong>Verificare rapidă</strong><span>Deschide mesajul trimis de Nordvale și apasă butonul de confirmare. Linkul rămâne valid 24 de ore.</span></span></div>
      </div>
    </section>

    <section class="auth">
      <div class="auth-inner">
        <a class="back" href="/autentificare"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m15 18-6-6 6-6"/></svg>Înapoi la autentificare</a>
        <article class="form-card">
          <div id="pendingState">
            <p class="form-kicker">Verificare email</p>
            <h2 class="form-title">Verifică-ți inboxul.</h2>
            <p class="form-copy">Am trimis un mesaj de confirmare către adresa asociată contului tău.</p>
            <div class="mail-visual" aria-hidden="true"><div class="mail-shadow"></div><div class="letter"><span class="letter-line"></span><span class="letter-line"></span><span class="letter-line"></span></div><div class="envelope"></div><div class="mail-badge"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3"><path d="m6 12 4 4 8-9"/></svg></div></div>
            <div class="email-chip"><span id="currentEmail">andrei.popescu@email.ro</span><button id="editEmailButton" type="button">Schimbă adresa</button></div>
            <div class="status-box"><span class="status-icon"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg></span><span><strong>Mesaj trimis</strong><span>Verifică și folderele Spam sau Promotions. Expeditorul este account@nordvale.demo.</span></span></div>
            <div class="actions"><button class="primary" id="openMailButton" type="button"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 4h16v16H4z"/><path d="m4 7 8 6 8-6"/></svg>Deschide aplicația de email</button><button class="secondary" id="resendButton" type="button" disabled><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12a9 9 0 1 1-3-6.7"/><path d="M21 3v6h-6"/></svg>Retrimite mesajul</button></div>
            <p class="countdown" id="countdown">Poți retrimite mesajul în <strong>30 secunde</strong>.</p>
            <div class="edit-panel" id="editPanel" hidden>
              <div class="field"><label for="newEmail">Adresă nouă de email</label><input class="input" id="newEmail" type="email" autocomplete="email" placeholder="nume@email.ro"><div class="field-error" id="emailError"></div></div>
              <div class="edit-actions"><button class="primary" id="saveEmailButton" type="button">Salvează și retrimite</button><button class="secondary" id="cancelEditButton" type="button">Anulează</button></div>
            </div>
            <div class="help-grid"><div class="help-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 5h18v14H3z"/><path d="m3 7 9 6 9-6"/></svg><span><strong>Mesajul nu apare?</strong><span>Caută după „Nordvale” și verifică folderele secundare.</span></span></div><div class="help-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 21s7-4.4 7-11V5l-7-2-7 2v5c0 6.6 7 11 7 11Z"/></svg><span><strong>Link securizat</strong><span>Confirmarea poate fi folosită o singură dată și expiră automat.</span></span></div></div>
          </div>

          <div id="successState" hidden>
            <p class="form-kicker">Email confirmat</p>
            <h2 class="form-title">Contul tău este activ.</h2>
            <div class="success"><div class="success-mark"><svg width="35" height="35" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 21s7-4.4 7-11V5l-7-2-7 2v5c0 6.6 7 11 7 11Z"/><path d="m8.5 12 2.2 2.2 4.8-5"/></svg></div><h3>Bine ai venit în Nordvale.</h3><p>Adresa ta a fost verificată. Biletele, comenzile și preferințele pot fi gestionate acum din cont.</p><span class="success-badge"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 12 4 4 8-9"/></svg>Cont verificat</span><div class="success-actions"><a class="primary" href="/cont">Intră în cont</a><a class="secondary" href="/">Explorează Nordvale</a></div></div>
          </div>
        </article>
      </div>
    </section>
  </main>
  <div class="toast" id="toast" role="status" aria-live="polite"></div>
</div>
<script>
(() => {
  'use strict';
  const $ = (selector, scope = document) => scope.querySelector(selector);
  const menu = $('#mobileMenu');
  const openMenu = () => { if (!menu) return; menu.classList.add('open'); menu.setAttribute('aria-hidden', 'false'); document.body.style.overflow = 'hidden'; };
  const closeMenu = () => { if (!menu) return; menu.classList.remove('open'); menu.setAttribute('aria-hidden', 'true'); document.body.style.overflow = ''; };
  $('#menuOpen')?.addEventListener('click', openMenu);
  $('#menuClose')?.addEventListener('click', closeMenu);
  document.addEventListener('keydown', event => { if (event.key === 'Escape') closeMenu(); });

  const currentEmail = $('#currentEmail');
  const editPanel = $('#editPanel');
  const newEmail = $('#newEmail');
  const emailError = $('#emailError');
  const resendButton = $('#resendButton');
  const countdown = $('#countdown');
  const toast = $('#toast');
  let remaining = 30;
  let timerId = null;

  const showToast = message => {
    if (!toast) return;
    toast.textContent = message;
    toast.classList.add('show');
    window.clearTimeout(showToast.timeout);
    showToast.timeout = window.setTimeout(() => toast.classList.remove('show'), 2800);
  };

  const startCountdown = () => {
    remaining = 30;
    resendButton.disabled = true;
    countdown.hidden = false;
    window.clearInterval(timerId);
    const render = () => { countdown.innerHTML = `Poți retrimite mesajul în <strong>${remaining} ${remaining === 1 ? 'secundă' : 'secunde'}</strong>.`; };
    render();
    timerId = window.setInterval(() => {
      remaining -= 1;
      if (remaining <= 0) {
        window.clearInterval(timerId);
        resendButton.disabled = false;
        countdown.innerHTML = 'Nu ai primit mesajul? Îl poți retrimite acum.';
        return;
      }
      render();
    }, 1000);
  };

  $('#editEmailButton')?.addEventListener('click', () => {
    editPanel.hidden = false;
    newEmail.value = currentEmail.textContent.trim();
    newEmail.focus();
    editPanel.animate([{ opacity: 0, transform: 'translateY(-8px)' }, { opacity: 1, transform: 'translateY(0)' }], { duration: 260, easing: 'ease-out' });
  });
  $('#cancelEditButton')?.addEventListener('click', () => { editPanel.hidden = true; emailError.textContent = ''; });
  $('#saveEmailButton')?.addEventListener('click', () => {
    const value = newEmail.value.trim();
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
    emailError.textContent = valid ? '' : 'Introdu o adresă de email validă.';
    if (!valid) { newEmail.focus(); return; }
    currentEmail.textContent = value;
    editPanel.hidden = true;
    showToast('Adresa a fost actualizată. Mesajul a fost retrimis.');
    startCountdown();
  });
  resendButton?.addEventListener('click', () => { showToast('Mesajul de verificare a fost retrimis.'); startCountdown(); });
  $('#openMailButton')?.addEventListener('click', () => { showToast('În demo, simulăm deschiderea aplicației de email.'); });

  try { const a = JSON.parse(localStorage.getItem('nordvale_auth') || 'null'); if (a && a.user && a.user.email && currentEmail) { currentEmail.textContent = a.user.email; } } catch (e) {}

  const query = new URLSearchParams(window.location.search);
  if (query.get('verified') === '1') {
    $('#pendingState').hidden = true;
    $('#successState').hidden = false;
  }

  document.addEventListener('keydown', event => {
    if (event.key.toLowerCase() === 'v' && (event.ctrlKey || event.metaKey) && event.shiftKey) {
      event.preventDefault();
      $('#pendingState').hidden = true;
      $('#successState').hidden = false;
      $('#successState').animate([{ opacity: 0, transform: 'translateY(14px)' }, { opacity: 1, transform: 'translateY(0)' }], { duration: 420, easing: 'cubic-bezier(.22,.8,.2,1)', fill: 'both' });
    }
  });

  startCountdown();
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    document.querySelectorAll('.visual-content > *').forEach((element, index) => element.animate([{ opacity: 0, transform: 'translateY(20px)' }, { opacity: 1, transform: 'translateY(0)' }], { duration: 650, delay: 120 + index * 90, easing: 'cubic-bezier(.22,.8,.2,1)', fill: 'both' }));
    $('.mail-visual')?.animate([{ transform: 'translateY(0) rotate(0deg)' }, { transform: 'translateY(-7px) rotate(1deg)' }, { transform: 'translateY(0) rotate(0deg)' }], { duration: 3600, iterations: Infinity, easing: 'ease-in-out' });
  }
})();
</script>
</body>
</html>
